/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate } from '../remotionShim';
import { noise2D } from "@remotion/noise";
import { makeLoadFont } from '../googleFonts';
const loadPlayball = makeLoadFont('Playball');
const loadAlexBrush = makeLoadFont('AlexBrush');
const loadGreatVibes = makeLoadFont('GreatVibes');

// Library: @remotion/noise - organic wobble for light leak elements

// Load elegant semi-cursive/script fonts for the brand logo
const { fontFamily: playballFont } = loadPlayball();
const { fontFamily: alexBrushFont } = loadAlexBrush();
const { fontFamily: greatVibesFont } = loadGreatVibes();



export type LightLeakTransitionProps = Record<string, any>;

const LightLeakTransition: React.FC<LightLeakTransitionProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 2,
  primaryColor = "#f4859a", // The dominant pink wash
  secondaryColor = "#ffe099", // The warm yellow/gold edge
  coreColor = "#ffffff", // The bright blown-out core
  blurAmount = 80,
  numberOfBumps = 6,
  angle = 12, // Subtle tilt for organic feel
  logoText = "Skin By Sammy",
  showLogo = true,
  logoColor = "#ffffff",
  logoScale = 1.2,
  logoFontSize = 76,
  logoFontFamily = "Alex Brush",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;
  const durationInFrames = Math.round(durationInSeconds * fps);

  // Parser safety for transparent background
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Base pink wash opacity - fades in to tint the screen before the bright core hits
  const pinkWashOpacity = interpolate(
    frame,
    [0, durationInFrames * 0.2, durationInFrames * 0.8, durationInFrames],
    [0, 0.85, 0.85, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Sweep animation - moves the entire light band entirely across the screen
  const sweepX = interpolate(
    frame,
    [0, durationInFrames],
    [-width * 2, width * 3],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Overall band opacity for smooth entrance/exit
  const sweepOpacity = interpolate(
    frame,
    [0, durationInFrames * 0.15, durationInFrames * 0.85, durationInFrames],
    [0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Pre-calculate an array for mapping the organic bumps along the edge
  const circles = useMemo(() => {
    return Array.from({ length: numberOfBumps }, (_, i) => i);
  }, [numberOfBumps]);

  // Dynamic font mapping helper
  const getFontFamily = (fontName: string) => {
    if (fontName === "Great Vibes") return greatVibesFont;
    if (fontName === "Playball") return playballFont;
    return alexBrushFont;
  };

  // Logo Animations timed precisely with the light leak transition sweep
  const logoOpacity = interpolate(
    frame,
    [0, durationInFrames * 0.2, durationInFrames * 0.35, durationInFrames * 0.8, durationInFrames],
    [0, 0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const logoTranslateY = interpolate(
    frame,
    [durationInFrames * 0.2, durationInFrames * 0.45],
    [30 * s, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const logoScaleIn = interpolate(
    frame,
    [durationInFrames * 0.2, durationInFrames * 0.45],
    [0.9, 1.0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Draw circle stroke logic (perimeter of circle of r=80 is ~503)
  const circleOffset = interpolate(
    frame,
    [durationInFrames * 0.2, durationInFrames * 0.5],
    [503, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Fade in delicate botanical leaves slightly after circle starts drawing
  const botanicalOpacity = interpolate(
    frame,
    [durationInFrames * 0.4, durationInFrames * 0.55],
    [0, 0.85],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Cursive text fade-in
  const textOpacity = interpolate(
    frame,
    [durationInFrames * 0.3, durationInFrames * 0.5],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <AbsoluteFill style={{ transition: "none" }}>
        
        {/* 1. Base Pink Wash Layer */}
        <AbsoluteFill
          style={{
            backgroundColor: primaryColor,
            opacity: pinkWashOpacity,
            transition: "none",
          }}
        />

        {/* 2. Sweeping Light Band */}
        <div
          style={{
            position: "absolute",
            left: 0,
            top: -height * 0.5,
            width: "100%",
            height: height * 2,
            transform: `translateX(${sweepX}px) rotate(${angle}deg)`,
            opacity: sweepOpacity,
            filter: `blur(${blurAmount * s}px)`,
            transition: "none",
            transformOrigin: "center center",
          }}
        >
          {/* Trail Gradient: Fades from transparent -> pink -> yellow -> pure white core */}
          <div
            style={{
              position: "absolute",
              left: -width * 2,
              top: 0,
              width: width * 2,
              height: "100%",
              background: `linear-gradient(to right, transparent 0%, ${primaryColor} 50%, ${secondaryColor} 85%, ${coreColor} 100%)`,
              transition: "none",
            }}
          />

          {/* Leading Wavy Edge: Organic overlapping circles to mimic uneven light bleed */}
          {circles.map((i) => {
            const containerHeight = height * 2;
            const yPos = interpolate(i, [0, numberOfBumps - 1], [0, containerHeight]);

            // Organic noise for radius and X position to create a living, wobbling edge
            const baseRadius = 280 * s;
            const radius = baseRadius + noise2D("radius", i, frame / 30) * 120 * s;
            const xOffset = noise2D("xOffset", i, frame / 20) * 90 * s;

            return (
              <div
                key={i}
                style={{
                  position: "absolute",
                  left: xOffset - radius, // Centered at the leading edge (0) with offset
                  top: yPos - radius,
                  width: radius * 2,
                  height: radius * 2,
                  borderRadius: "50%",
                  background: `radial-gradient(circle, ${coreColor} 15%, ${secondaryColor} 50%, transparent 85%)`,
                  transition: "none",
                }}
              />
            );
          })}
        </div>

        {/* 3. Secondary Wash for Volumetric Depth */}
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: "100%",
            height: "100%",
            transform: `translateX(${sweepX * 0.75}px) rotate(${angle * -0.5}deg)`,
            opacity: sweepOpacity * 0.6,
            filter: `blur(${blurAmount * 1.5 * s}px)`,
            mixBlendMode: "screen",
            transition: "none",
            transformOrigin: "center center",
          }}
        >
          <div
            style={{
              position: "absolute",
              left: -width * 0.5,
              top: height * 0.2,
              width: width * 1.5,
              height: height * 0.8,
              background: `radial-gradient(ellipse at center, ${secondaryColor} 0%, transparent 70%)`,
              borderRadius: "50%",
              transition: "none",
            }}
          />
        </div>

        {/* 4. Highly Elegant Semi-Cursive Logo Overlay */}
        {showLogo && (
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              top: 0,
              bottom: 0,
              display: "flex",
              flexDirection: "column",
              justifyContent: "center",
              alignItems: "center",
              opacity: logoOpacity,
              transform: `translateY(${logoTranslateY}px) scale(${logoScaleIn})`,
              transition: "none",
              pointerEvents: "none",
            }}
          >
            <div style={{ position: "relative", display: "flex", justifyContent: "center", alignItems: "center" }}>
              {/* Decorative SVG circular badge outline with organic leaves */}
              <svg
                viewBox="0 0 200 200"
                style={{
                  width: 320 * s * logoScale,
                  height: 320 * s * logoScale,
                  transition: "none",
                }}
              >
                {/* Thin aesthetic circle */}
                <circle
                  cx="100"
                  cy="100"
                  r="80"
                  fill="none"
                  stroke={logoColor}
                  strokeWidth="1.5"
                  strokeDasharray="503"
                  strokeDashoffset={circleOffset}
                  strokeLinecap="round"
                  opacity={0.8}
                />
                {/* Top delicate leaves */}
                <path
                  d="M 100 20 C 103 16, 110 18, 107 24 C 104 27, 101 24, 100 20 Z"
                  fill={logoColor}
                  opacity={botanicalOpacity}
                  transform="rotate(-15 100 20)"
                />
                <path
                  d="M 100 20 C 97 16, 90 18, 93 24 C 96 27, 99 24, 100 20 Z"
                  fill={logoColor}
                  opacity={botanicalOpacity}
                  transform="rotate(15 100 20)"
                />
                {/* Bottom delicate leaves */}
                <path
                  d="M 100 180 C 103 184, 110 182, 107 176 C 104 173, 101 176, 100 180 Z"
                  fill={logoColor}
                  opacity={botanicalOpacity}
                  transform="rotate(15 100 180)"
                />
                <path
                  d="M 100 180 C 97 184, 90 182, 93 176 C 96 173, 99 176, 100 180 Z"
                  fill={logoColor}
                  opacity={botanicalOpacity}
                  transform="rotate(-15 100 180)"
                />
              </svg>

              {/* Styled Clean Semi-Cursive Text Overlay */}
              <div
                style={{
                  position: "absolute",
                  fontFamily: getFontFamily(logoFontFamily),
                  fontSize: `${logoFontSize * s * logoScale}px`,
                  color: logoColor,
                  textAlign: "center",
                  lineHeight: 1.1,
                  whiteSpace: "nowrap",
                  opacity: textOpacity,
                  textShadow: `0 4px 15px rgba(0,0,0,0.1), 0 0 25px ${primaryColor}33`,
                  transition: "none",
                }}
              >
                {logoText}
              </div>
            </div>
          </div>
        )}

      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default LightLeakTransition;